// Texture-table closure of original744b70 token resolver; no extra entry credit.
using System;namespace Recovered.Gameplay {public static class PtlTokenTextures {static Func<SoundSetupImage,uint,uint[],uint> Calls(Func<SoundSetupImage,uint,uint[],uint> external){return delegate(SoundSetupImage m,uint address,uint[] values){return address==0x5e5310?PtlTextureLookup.Lookup(m,unchecked((int)values[0])):external(m,address,values);};}public static byte[] ResolveDescriptor(SoundSetupImage m,uint output,uint key,uint force,Func<SoundSetupImage,uint,uint[],uint> external){return PtlTokenDescriptor.ResolveDescriptor(m,output,key,force,Calls(external));}public static uint Values(SoundSetupImage m,uint[] key,uint force,Func<SoundSetupImage,uint,uint[],uint> external){return PtlTokenDescriptor.Values(m,key,force,Calls(external));}}}
